"use client";

import { useState, useEffect } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription, DialogFooter } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { createNewTask, updateTask } from "@/app/actions/task-actions";

export default function TaskFormModal({ isOpen, onClose, editingTask }: any) {
  const [title, setTitle] = useState("");
  const [content, setContent] = useState("");
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (editingTask) {
      setTitle(editingTask.title);
      setContent(editingTask.content || "");
    } else {
      setTitle("");
      setContent("");
    }
  }, [editingTask, isOpen]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    const res = editingTask ? await updateTask(editingTask.id, { title, content }) : await createNewTask(title, content);
    if (res.success) onClose();
    setLoading(false);
  };

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="bg-white">
        <form onSubmit={handleSubmit}>
          <DialogHeader>
            <DialogTitle>{editingTask ? "Bewerken" : "Nieuwe Taak"}</DialogTitle>
            <DialogDescription>Vul de gegevens in.</DialogDescription>
          </DialogHeader>
          <div className="grid gap-4 py-4">
            <div className="grid gap-2">
              <Label>Titel</Label>
              <Input value={title} onChange={(e) => setTitle(e.target.value)} required />
            </div>
            <div className="grid gap-2">
              <Label>Inhoud</Label>
              <Textarea value={content} onChange={(e) => setContent(e.target.value)} className="min-h-[150px]" />
            </div>
          </div>
          <DialogFooter>
            <Button type="button" variant="outline" onClick={onClose}>Annuleren</Button>
            <Button type="submit" disabled={loading}>{loading ? "Laden..." : "Opslaan"}</Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}