"use client";

import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Plus } from "lucide-react";
import TaskFormModal from "./TaskFormModal";
import { deleteTask } from "@/app/actions/task-actions";

export default function TaskListClient({ initialTasks }: { initialTasks: any[] }) {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingTask, setEditingTask] = useState<any>(null);

  return (
    <div className="p-4">
      <div className="flex justify-between mb-6">
        <h1 className="text-2xl font-bold">Mijn Taken</h1>
        <Button onClick={() => { setEditingTask(null); setIsModalOpen(true); }} className="bg-blue-600 text-white">
          <Plus className="mr-2" /> Nieuwe Taak
        </Button>
      </div>

      <div className="grid gap-4">
        {initialTasks.map((task) => (
          <div key={task.id} className="p-4 border rounded shadow-sm flex justify-between bg-white">
            <div>
              <h3 className="font-bold">{task.title}</h3>
              <p className="text-sm text-gray-600">{task.content}</p>
            </div>
            <div className="flex gap-2">
              <Button variant="outline" onClick={() => { setEditingTask(task); setIsModalOpen(true); }}>Bewerken</Button>
              <Button variant="destructive" onClick={() => deleteTask(task.id)}>Verwijderen</Button>
            </div>
          </div>
        ))}
      </div>

      <TaskFormModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} editingTask={editingTask} />
    </div>
  );
}